import {form,field,text,area,number as num,select as sel,e,result,download,copyText,error} from '../ui.mjs';
import {bsMonths,holidays} from './nepal-data.mjs';
import {bsToAD,adToBS,devanagari} from './nepal-core.mjs';
import {dateUTC} from '../core.mjs';
import {today,table,exportCSV,need} from './shared.mjs';
import {pageSVG,pagesResult,svgTextLines} from './plus-svg.mjs';
const monthNames=['Baisakh · वैशाख','Jestha · जेठ','Asar · असार','Shrawan · साउन','Bhadra · भदौ','Ashwin · असोज','Kartik · कात्तिक','Mangsir · मंसिर','Poush · पुस','Magh · माघ','Falgun · फागुन','Chaitra · चैत'];
let fontPromise;
export function nepaliFontCSS(){if(!fontPromise)fontPromise=Promise.all(['noto-sans-devanagari.woff2','noto-sans-devanagari-latin.woff2'].map(name=>fetch(new URL('../assets/fonts/'+name,import.meta.url)).then(r=>{if(!r.ok)throw Error('Could not load the bundled Nepali font. Reconnect and try again.');return r.arrayBuffer();}).then(buffer=>{const data=new Uint8Array(buffer);let binary='';for(let i=0;i<data.length;i+=8192)binary+=String.fromCharCode(...data.slice(i,i+8192));return btoa(binary);}))).then(([ne,latin])=>'<metadata>Copyright 2022 The Noto Project Authors. Noto Sans Devanagari 2.007, SIL Open Font License 1.1. License included with Nepocore.</metadata><style>@font-face{font-family:NepocoreNepali;src:url(data:font/woff2;base64,'+ne+') format("woff2");unicode-range:U+0900-097F,U+200C-200D,U+A8E0-A8FF,U+11B00-11B09}@font-face{font-family:NepocoreNepali;src:url(data:font/woff2;base64,'+latin+') format("woff2");unicode-range:U+0000-00FF,U+2000-200B,U+2010-206F}text{font-family:NepocoreNepali,Arial,sans-serif}</style>').catch(ex=>{fontPromise=null;throw ex;});return fontPromise;}
export function bsCalendar(year,month){need(bsMonths[year]&&month>=1&&month<=12,'Choose a BS year from 2000–2090 and month from 1–12.');const count=bsMonths[year][month-1],start=bsToAD(year+'-'+String(month).padStart(2,'0')+'-01'),weekday=dateUTC(start).getUTCDay(),dates=Array.from({length:count},(_,i)=>({day:i+1,ad:bsToAD(year+'-'+String(month).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'))}));return {year,month,count,start,weekday,dates};}
const cashRows=[['n1000',1000,'Note'],['n500',500,'Note'],['n100',100,'Note'],['n50',50,'Note'],['n20',20,'Note'],['n10',10,'Note'],['n5',5,'Note'],['c2',2,'Coin'],['c1',1,'Coin'],['n250',250,'Uncommon note'],['n25',25,'Uncommon note'],['n2',2,'Uncommon note'],['n1',1,'Uncommon note']];
export function cashCount(values,includeUncommon=false){const list=cashRows.filter((_,i)=>includeUncommon||i<9).map(([id,denomination,kind])=>{const quantity=Number(values[id]||0);need(Number.isSafeInteger(quantity)&&quantity>=0&&quantity<=1e9,'Use nonnegative whole quantities up to one billion.');return {kind,denomination,quantity,amount:denomination*quantity};});return {list,total:list.reduce((s,r)=>s+r.amount,0),pieces:list.reduce((s,r)=>s+r.quantity,0)};}
export function nepaliLetter(v){const subject=v.type==='school'?'विद्यालय बिदा सम्बन्धमा।':v.type==='office'?'बिदा स्वीकृत गरिदिने सम्बन्धमा।':v.subject||'निवेदन सम्बन्धमा।',request=v.type==='general'?v.reason:`${v.reason} कारणले ${v.start} देखि ${v.end} सम्म बिदा आवश्यक परेकोले उक्त अवधिका लागि बिदा स्वीकृत गरिदिनुहुन विनम्र अनुरोध गर्दछु।`;return `मिति: ${v.date}\n\nश्री ${v.recipient},\n${v.institution}\n${v.address}\n\nविषय: ${subject}\n\nमहोदय/महोदया,\n\n${request}\n\n${v.additional||''}\n\nभवदीय,\n${v.applicant}\n${v.role}\n${v.contact?`सम्पर्क: ${v.contact}`:''}`.replace(/\n{3,}/g,'\n\n').trim();}
export function setupNepalPlus(tool,mount,out){mount.classList.add('nepali-tool');if(tool.id==='npr-cash-counter')return cash(mount,out);if(tool.id==='nepali-calendar')return calendar(mount,out);return letter(mount,out);}
function cash(mount,out){const fields=[sel('uncommon','Include uncommon older note rows',[['no','Common notes and Rs1/Rs2 coins'],['yes','Also show 250/25/2/1 note rows']],'no'),...cashRows.map(([id,value,kind])=>num(id,'NPR '+value+' · '+kind,0,0,1e9,1))],f=form(mount,fields,v=>{const r=cashCount(v,v.uncommon==='yes');result(out,{label:'Recorded cash total',value:'NPR '+r.total.toLocaleString(),details:[['Pieces of cash',r.pieces]],html:table(['Type','Denomination','Quantity','Amount'],r.list.filter(r=>r.quantity).map(r=>[r.kind,'NPR '+r.denomination,r.quantity,'NPR '+r.amount])),note:'Manual arithmetic only. Count notes and coins separately. Uncommon older notes are not described as invalid.'});if(r.pieces)exportCSV(out,r.list.filter(r=>r.quantity),'nepocore-npr-cash-count.csv');},{label:'Total the cash'});function visibility(){cashRows.slice(9).forEach(([id])=>{f.elements[id].closest('.field').hidden=f.elements.uncommon.value!=='yes';f.elements[id].disabled=f.elements.uncommon.value!=='yes';});}f.elements.uncommon.onchange=()=>{visibility();f.requestSubmit();};visibility();}
function calendar(mount,out){let disposed=false;let current;try{current=adToBS(today()).split('-').map(Number);}catch{current=[2083,1,1];}form(mount,[num('year','BS year',current[0],2000,2090,1),sel('month','BS month',monthNames.map((name,i)=>[i+1,name]),current[1]),sel('digits','Day numerals',[['nepali','नेपाली अङ्क'],['english','English digits']],'nepali')],async v=>{const data=bsCalendar(+v.year,+v.month),font=await nepaliFontCSS();if(disposed)return;const digit=value=>v.digits==='nepali'?devanagari(value):String(value),cw=102,rh=105,left=40,top=155,rows=Math.ceil((data.weekday+data.count)/7),notes=(+v.year===2083?holidays:[]).filter(h=>String(h.dateBS||'').startsWith(v.year+'-'+String(v.month).padStart(2,'0')+'-'));let body='';['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach((name,i)=>body+=`<text x="${left+(i+.5)*cw}" y="137" text-anchor="middle" font-size="14" font-weight="700">${name}</text>`);for(let i=0;i<rows*7;i++){const day=i-data.weekday+1,x=left+i%7*cw,y=top+Math.floor(i/7)*rh;body+=`<rect x="${x}" y="${y}" width="${cw}" height="${rh}" fill="white" stroke="#b2c2b5"/>`;if(day>0&&day<=data.count){const record=data.dates[day-1],holiday=notes.some(h=>+(String(h.dateBS).slice(-2))===day);body+=`<text x="${x+12}" y="${y+42}" font-size="29" fill="${i%7===6||holiday?'#9f463e':'#263c33'}">${digit(day)}</text><text x="${x+12}" y="${y+72}" font-size="11">AD ${record.ad.slice(5)}</text>`;}}const y=top+rows*rh+38;body+=`<text x="40" y="${y}" font-size="13">${+v.year===2083?'Dated holiday notes, where available, are listed on the following pages.':'No verified holiday overlay is bundled for this year.'}</text><text x="40" y="${y+28}" font-size="12">Calendar range: BS 2000–2090. Community and regional holidays have limited scope.</text>`;const pages=[pageSVG(monthNames[+v.month-1]+' '+digit(v.year),'AD '+data.start+' to '+data.dates.at(-1).ad,body).replace('<g font-family=',font+'<g font-family=')];for(let start=0;start<notes.length;start+=16){let list='';notes.slice(start,start+16).forEach((h,i)=>{const date=h.dateBS,label=h.name?.en||'Holiday',scope=h.scope||h.appliesTo||'Check official notice',text=date+' · '+label+' · '+scope;svgTextLines(text,67).slice(0,3).forEach((line,j)=>list+=`<text x="42" y="${145+i*53+j*16}" font-size="13">${e(line)}</text>`);});pages.push(pageSVG('Holiday notes · '+v.year,'MoHA notice. Scope matters; these are not all universal closures.',list).replace('<g font-family=',font+'<g font-family='));}pagesResult(out,pages,'nepocore-bs-calendar',{details:[['BS month',v.year+'-'+v.month],['First weekday',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][data.weekday]],['Holiday year',+v.year===2083?'2083 only':'No verified overlay']],note:'Calendar dates use the bundled BS month table. Holiday notes are limited to available dated 2083 records; always check the official notice for scope and changes.'});exportCSV(out,data.dates.map(d=>({bs:v.year+'-'+String(v.month).padStart(2,'0')+'-'+String(d.day).padStart(2,'0'),ad:d.ad})),'nepocore-bs-month.csv');},{label:'Create printable calendar'});return()=>{disposed=true;};}
function letter(mount,out){let disposed=false;let date;try{date=adToBS(today())+' बी.सं.';}catch{date=today();}const f=form(mount,[sel('type','Letter type',[['school','School leave'],['office','Office leave'],['general','General request']],'school'),text('date','Date',date),text('recipient','Recipient / title','प्रधानाध्यापकज्यू'),text('institution','Institution','नमुना विद्यालय'),text('address','Institution address','काठमाडौं'),text('subject','Subject for general request','आवश्यक सहयोग सम्बन्धमा।'),area('reason','Reason / request','व्यक्तिगत काम'),text('start','Leave start date','२०८३/०७/१२'),text('end','Leave end date','२०८३/०७/१३'),text('applicant','Applicant name','नमुना विद्यार्थी'),text('role','Class / role','कक्षा: १०'),{...text('contact','Contact (optional)',''),required:false},{...area('additional','Additional details (optional)',''),required:false}],v=>{need(Object.values(v).every(value=>value.length<=2000),'Keep each field to 2,000 characters.');const doc=nepaliLetter(v);result(out,{html:'<label class="field"><span>Editable final letter</span><textarea class="nepali-output" data-letter-final rows="20">'+e(doc)+'</textarea></label><div class="result-actions"><button class="btn secondary" data-letter-copy>Copy letter</button><button class="btn secondary" data-letter-txt>Download TXT</button><button class="btn primary" data-letter-pdf>Prepare printable pages</button></div>',note:'Proofread names, dates, tone and the request. This is an original editable template, not an official form or a promise of acceptance.'});const edit=out.querySelector('[data-letter-final]');out.querySelector('[data-letter-copy]').onclick=()=>copyText(edit.value);out.querySelector('[data-letter-txt]').onclick=()=>download(new Blob([edit.value],{type:'text/plain;charset=utf-8'}),'nepocore-nepali-letter.txt');out.querySelector('[data-letter-pdf]').onclick=async ev=>{const b=ev.currentTarget;b.disabled=true;try{const font=await nepaliFontCSS();if(disposed||!b.isConnected)return;const lines=edit.value.split('\n').flatMap(line=>line?svgTextLines(line,50):['']),pages=[];for(let start=0;start<lines.length;start+=36){const body=lines.slice(start,start+36).map((line,i)=>`<text x="48" y="${140+i*25}" font-size="19">${e(line)}</text>`).join('');pages.push(pageSVG('निवेदन','सम्पादन गरिएको नमुना पत्र · विवरण जाँच गरेर मात्र प्रयोग गर्नुहोस्।',body).replace('<g font-family=',font+'<g font-family='));}pagesResult(out,pages,'nepocore-nepali-letter',{note:'These pages reflect the edited letter. The PDF appearance is rasterized for Nepali-script shaping; keep the TXT copy for editable text.'});}catch(ex){if(b.isConnected)error(out,ex.message);}finally{if(b.isConnected)b.disabled=false;}};},{label:'Draft Nepali letter',note:'Editable templates only. Use the receiving institution’s official form if it requires one.'});function visibility(){for(const name of ['start','end']){f.elements[name].closest('.field').hidden=f.elements.type.value==='general';f.elements[name].disabled=f.elements.type.value==='general';}f.elements.subject.closest('.field').hidden=f.elements.type.value!=='general';f.elements.subject.disabled=f.elements.type.value!=='general';}f.elements.type.onchange=()=>{visibility();f.requestSubmit();};visibility();return()=>{disposed=true;};}
